import {MOVES} from './combat-moves.mjs';
export const EMPTY_MOVE={id:0,sdId:'',name:'Emplacement libre',type:'normal',power:0,accuracy:100,pp:0,status:true,special:false,supported:true,empty:true};
export function enrichSpecies(d){if(!d)return d;if(!d._movesEnriched){d.learnset=(d.learnset||d.moves||[]).filter(m=>MOVES[m.id]).map(m=>({...MOVES[m.id],...m}));d.moves=(d.moves||[]).filter(m=>MOVES[m.id]).map(m=>({...MOVES[m.id],...m}));Object.defineProperty(d,'_movesEnriched',{value:true,enumerable:false,configurable:true})}return d}
export function legalMove(d,id){return !!MOVES[id]&&id!==165&&((d.sdId==='smeargle'&&!MOVES[id].flags?.nosketch)||(d.legalMoves?d.legalMoves.includes(id):(d.learnset||d.moves||[]).some(m=>m.id===id)||(d.tmMoves||[]).includes(id)))}
export function availableMoves(d,p,L){enrichSpecies(d);const moves=new Map(d.learnset.filter(m=>m.level<=L).map(m=>[m.id,m]));for(const id of [...(p.taughtMoves||[]),...(p.retainedMoves||[])])if(legalMove(d,id))moves.set(id,{...MOVES[id],method:p.taughtMoves?.includes(id)?'appris':'hérité'});return [...moves.values()]}
export function selectedMoves(d,p,L){const available=availableMoves(d,p,L),allowed=new Map(available.map(m=>[m.id,m])),used=new Set();if(!p.moves?.length){p.moves=available.slice(-4).map(m=>m.id)}const corrected=[];let changed=false;for(const id of p.moves.slice(0,4)){if(id&&id!==165&&allowed.has(id)&&!used.has(id)){corrected.push(id);used.add(id)}else{corrected.push(0);if(id){p.retiredMoves=[...new Set([...(p.retiredMoves||[]),id])];changed=true}}}if(!corrected.some(Boolean)&&available.length){corrected[0]=available[0].id;changed=true}while(corrected.length<4)corrected.push(0);p.moves=corrected;if(changed)p.moveReviewNotice=true;return corrected.map(id=>allowed.get(id)||EMPTY_MOVE)}
export function learningLabel(d,m){if(m.method==='appris')return 'Capacité déjà apprise';if(m.method==='hérité')return 'Capacité conservée après évolution';if(m.evolution)return 'À l’évolution';if(m.level)return 'Niveau '+m.level+' · Gén. '+(d.learnGeneration||9);if(d.tmMoves?.includes(m.id))return 'CT compatible';if(d.tutorMoves?.includes(m.id))return 'Maître des capacités';return 'Capacité héritée'}
